/* FitFirst V2 — Showroom Console shell: login, masthead navigation, role-aware Today, presenter notes.
   Keeps the real console's identity (dashboard/src/App.tsx): editorial masthead with centred view tabs,
   theme toggle, "Launch kiosk", Lock, and a PIN keypad with discrete digit cells. */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$;
  FF.pages = {};
  FF.page = (name, def) => { FF.pages[name] = def; };
  const ALL = ['OWNER', 'MANAGER', 'STAFF', 'INTAKE'], MGR = ['OWNER', 'MANAGER'];
  FF.ROLES = { ALL, MGR, FLOOR: ['OWNER', 'MANAGER', 'STAFF'], STOCK: ['OWNER', 'MANAGER', 'INTAKE'] };
  /* information architecture: six sections in the masthead (the real console has four), each with its own sub-pages */
  const SECTIONS = [
    { id: 'today', label: 'Today', icon: 'home', pages: ['home'] },
    { id: 'sessions', label: 'Sessions', icon: 'users', pages: ['queue', 'visits'], badge: 'sessions' },
    { id: 'inventory', label: 'Inventory', icon: 'hanger', pages: ['catalogue', 'intake', 'review', 'inward', 'import', 'count', 'labels'], badge: 'review' },
    { id: 'counter', label: 'Counter', icon: 'bill', pages: ['billing', 'sales', 'dayclose'] },
    { id: 'analytics', label: 'Analytics', icon: 'chart', pages: ['analytics', 'clearance', 'gaps', 'team'] },
    { id: 'baseline', label: 'Baseline Log', icon: 'book', pages: ['baseline', 'pilot'] },
    { id: 'setup', label: 'Setup', icon: 'settings', pages: ['settings', 'onboarding', 'pitch', 'platform'] },
  ];
  /* sub-page names match V1's menu so nothing is hard to find */
  const SUBLABEL = { queue: 'Live queue', visits: 'Visits', analytics: 'Results', baseline: 'Daily log', pilot: 'Pilot scorecard' };
  const route = () => { const h = location.hash.replace(/^#\/?/, '').split('/'); let name = h[0] || 'home'; name = { today: 'home', visit: 'session', sessions: 'queue', insights: 'analytics' }[name] || name; /* old V1 and real-app links keep working */ return { name, args: h.slice(1).map(decodeURIComponent) }; };
  const sectionOf = (name) => { const pg = FF.pages[name]; const n = pg && pg.parent ? pg.parent : name; return SECTIONS.find((s) => s.pages.includes(n)); };
  FF.go = (h) => { if (location.hash === h) FF.render(); else location.hash = h; };
  FF.act('go', (d) => FF.go(d.to));
  const can = (pg) => { const me = FF.me(); return !!(me && pg && pg.roles.includes(me.role)); };
  FF.counts = () => { const db = FF.db; return { sessions: db.visits.filter((v) => v.status === 'WAITING').length + db.help.filter((h) => !h.done).length, queue: db.visits.filter((v) => v.status === 'WAITING').length, review: db.products.filter((p) => p.status === 'IN_REVIEW').length, labels: db.labelQueue.length, gaps: db.gaps.filter((g) => g.fresh).length, import: db.syncIssues.filter((i) => !i.done).length }; };

  /* presenter notes: one line per screen for whoever is demonstrating */
  const NOTES = {
    home: ['Start here', 'Each person sees their own Today. The owner sees money and attention items; a salesperson sees who is waiting; intake sees stock tasks.'],
    sessions: ['The bridge from kiosk to floor', 'A shopper finishes on the kiosk, tablet or phone and appears here within seconds. Claim one, or search the code they show you.'],
    session: ['What the salesperson brings', 'Picks with rack locations, why each suits the shopper, and a line to say. Tap Tried, Rejected or Add to bill — that is all staff need to do.'],
    catalogue: ['Stock by size, age by lot', 'Every piece shows sizes left and how long it has been in the shop. Older stock is what FitFirst helps clear.'],
    intake: ['About 90 seconds a piece', 'Photo, tag, barcode. AI fills the details; staff confirm only what it was unsure about. Nothing is guessed silently.'],
    billing: ['Optional: FitFirst Billing', 'For shops without good billing software. Scan the shopper’s QR and the sale is linked to their visit automatically. GST is worked out per piece.'],
    analytics: ['Proof, not promises', 'Every number comes from a bill or a staff tap. The control group shows how much extra old stock sold because of FitFirst.'],
    clearance: ['The owner’s dial', 'Turn the clearance nudge up or down. The side-by-side shows it never pushes a piece that suits clearly worse.'],
    gaps: ['A buying list', 'What shoppers asked for that the shop did not have — by category, size, budget and occasion.'],
    baseline: ['The before-and-after', 'Daily totals before and during the pilot. The pass marks are locked in writing before go-live.'],
  };
  const presenterOn = () => { try { return localStorage.getItem('ff2_presenter') === '1'; } catch (e) { return false; } };

  FF.render = () => {
    const me = FF.me(), root = $('#root'); if (!me) { root.innerHTML = login(); return; }
    const r = route(), pg = FF.pages[r.name], sec = sectionOf(r.name), c = FF.counts(), f = FF.db.settings.flags, st = FF.store();
    const main = $('.view'), keep = main && main.dataset.route === location.hash ? window.scrollY : 0;
    const body = !pg ? U.empty('search', 'Page not found', 'That screen does not exist.', `<a class="btn" href="#/home">Go to Today</a>`) : !can(pg) ? U.empty('lock', '“' + esc(pg.title) + '” is for other roles', `You are signed in as ${esc(me.name)} (${esc(FF.TAX.roles[me.role])}). This page is for: ${esc(WHO(pg))}.`, `<div class="row" style="justify-content:center"><a class="btn" href="#/home">Go to Today</a><button class="btn btn-p" data-act="lock">Switch person</button></div>`) : pg.render(...r.args);
    const visSecs = SECTIONS.filter((s) => s.pages.some((p) => can(FF.pages[p])));
    const subs = sec ? sec.pages.filter((p) => can(FF.pages[p])) : [];
    const firstOf = (s) => s.pages.find((p) => can(FF.pages[p]));
    const tabLabel = (s) => { const vis = s.pages.filter((p) => can(FF.pages[p])); return vis.length === 1 && s.pages.length > 1 ? (SUBLABEL[vis[0]] || FF.pages[vis[0]].title) : s.label; };
    const badge = (s) => (s.badge && c[s.badge] && can(FF.pages[{ sessions: 'queue', review: 'review' }[s.badge]]) ? `<span class="cnt">${c[s.badge]}</span>` : '');
    const note = presenterOn() && NOTES[r.name] && !FF._noteHidden ? `<aside class="presenter" role="note"><div class="row between"><span class="eyebrow">Presenter · ${esc(NOTES[r.name][0])}</span><button class="x" style="width:26px;height:26px;color:inherit" data-act="note-x" aria-label="Hide note">${FF.icon('x')}</button></div><p>${esc(NOTES[r.name][1])}</p></aside>` : '';
    root.innerHTML = `<header class="mast"><a class="brand" href="#/home"><span class="monogram">F</span><span class="t">FitFirst</span></a>
      <nav class="mtabs" aria-label="Sections">${visSecs.filter((s) => !s.hidden).map((s) => `<a href="#/${firstOf(s)}" ${sec === s ? 'aria-current="page"' : ''}>${FF.icon(s.icon)}${tabLabel(s)}${badge(s)}</a>`).join('')}</nav>
      <div class="mact"><form class="find hide-m" data-submit="find-code" role="search">${FF.icon('search')}<input name="code" placeholder="Find a handoff code" aria-label="Find a shopper by handoff code" required pattern="[Ff]{0,2}-?[A-Za-z0-9]{4}" data-msg="Codes look like FF-7K2Q"></form>
        ${U.demo('Demo')}<button class="iconbtn" data-act="theme" title="Light / dark" aria-label="Switch theme">${FF.icon(document.documentElement.dataset.theme === 'dark' ? 'spark' : 'eye')}</button>
        <a class="iconbtn hide-m" href="kiosk.html${me.role === 'STAFF' ? '?mode=assisted' : ''}" target="_blank" rel="noopener" title="Launch kiosk" aria-label="Launch kiosk">${FF.icon('phone')}</a>
        <button class="iconbtn" data-act="allpages" title="All pages" aria-label="All pages">${FF.icon('menu')}</button>
        <button class="btn btn-g" style="padding:0 6px" data-act="pop" data-menu="me" aria-label="Account"><span class="avatar">${esc(me.code)}</span></button></div></header>
      ${subs.length > 1 ? `<nav class="subnav" aria-label="${esc(sec.label)}">${subs.map((p) => `<a href="#/${p}" ${r.name === p ? 'aria-current="page"' : ''}>${SUBLABEL[p] || FF.pages[p].title}${p === 'review' && c.review ? `<span class="cnt">${c.review}</span>` : p === 'import' && c.import ? `<span class="cnt">${c.import}</span>` : p === 'labels' && c.labels ? `<span class="badge">${c.labels}</span>` : ''}</a>`).join('')}</nav>` : ''}
      ${f.aiOff ? `<div class="banner bad">${FF.icon('alert')} AI tagging is off — new pieces can still be added by hand; nothing is guessed. <a class="link" href="#/settings/demo">Details</a></div>` : ''}${f.offline ? `<div class="banner warn">${FF.icon('wifioff')} Working offline. Bills use this counter’s own number series and sync when the connection returns.</div>` : ''}
      <main class="view" data-route="${esc(location.hash)}">${body}</main>
      <nav class="tabbar" aria-label="Sections">${visSecs.slice(0, 4).map((s) => `<a href="#/${firstOf(s)}" ${sec === s ? 'aria-current="page"' : ''}>${FF.icon(s.icon)}${tabLabel(s)}${badge(s)}</a>`).join('')}${visSecs.length > 4 ? `<a href="#" data-act="allpages" ${visSecs.slice(4).includes(sec) ? 'aria-current="page"' : ''}>${FF.icon('menu')}More</a>` : ''}</nav>${note}`;
    document.title = (pg ? pg.title + ' · ' : '') + 'FitFirst Console';
    if (keep) window.scrollTo(0, keep);
    if (pg && can(pg) && pg.after) pg.after(...r.args);
  };
  window.addEventListener('hashchange', () => { while ($('.scrim')) FF.closeOverlay(); FF._noteHidden = false; window.scrollTo(0, 0); FF.render(); });
  /* every page in one grouped list: the same map as V1's sidebar, for phones and for anyone looking for something */
  const WHO = (pg) => (pg.roles.length === 1 ? 'Owner only' : pg.roles.every((r) => MGR.includes(r)) ? 'Owner and manager' : pg.roles.includes('INTAKE') && !pg.roles.includes('STAFF') ? 'Owner, manager and intake' : 'Owner, manager and sales staff');
  FF.act('allpages', () => { $('.pop')?.remove(); const r = route(), c = FF.counts(), me = FF.me();
    const row = (p) => { const pg = FF.pages[p], ok = can(pg), n = { review: c.review, import: c.import, labels: c.labels, queue: c.sessions, gaps: c.gaps }[p];
      return ok ? `<a class="row" style="padding:10px 12px;border-radius:10px;text-decoration:none;${r.name === p ? 'background:var(--sub);font-weight:700' : ''}" href="#/${p}">${FF.icon(pg.icon)}<span class="grow inkc">${esc(SUBLABEL[p] || pg.title)}</span>${n ? `<span class="cnt">${n}</span>` : ''}</a>`
        : `<div class="row" style="padding:10px 12px;opacity:.55" title="${esc(WHO(pg))}">${FF.icon(pg.icon)}<span class="grow">${esc(SUBLABEL[p] || pg.title)}</span><span class="tiny muted row gap4">${FF.icon('lock')}${esc(WHO(pg))}</span></div>`; };
    const locked = SECTIONS.some((s) => s.pages.some((p) => !can(FF.pages[p])));
    FF.drawer({ title: 'All pages', sub: esc(me.name) + ' · ' + esc(FF.TAX.roles[me.role]), body: (locked ? `<p class="note n-plain small">Greyed pages belong to other roles. To demonstrate them, <button class="link" data-act="lock">switch person</button> — sign in as Hetal Shah (owner) or Kiran Desai (manager).</p>` : '') + SECTIONS.map((s) => `<h4 class="mt16 mb8">${esc(s.label)}</h4>${s.pages.map(row).join('')}`).join('') }); });
  FF.act('theme', () => { FF.theme(document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'); FF.render(); });
  FF.act('note-x', () => { FF._noteHidden = true; $('.presenter')?.remove(); });
  FF.act('find-code', (f) => { const c = 'FF-' + f.code.toUpperCase().replace(/^FF-?/, ''); if (!FF.db.visits.some((v) => v.code === c)) return FF.toast('No session with code ' + c, 'bad'); FF.go('#/session/' + c); });
  FF.menu('me', () => { const me = FF.me(); return `<div class="pop-text"><b class="inkc">${esc(me.name)}</b><br><span class="tiny">${FF.TAX.roles[me.role]} · ${esc(FF.store().name)}</span></div><hr style="margin:4px 0"><div class="pop-text tiny" style="padding-bottom:2px">Store</div>${FF.db.stores.map((x) => `<button data-act="store" data-id="${x.id}">${FF.icon('store')}<span>${esc(x.name)}<br><span class="tiny muted">${esc(x.area)}${x.id !== FF.db.storeId && FF.db.org.plan !== 'PREMIUM' ? ' · Premium' : ''}</span></span>${x.id === FF.db.storeId ? ' ✓' : ''}</button>`).join('')}<hr style="margin:4px 0"><button data-act="allpages">${FF.icon('menu')} All pages</button><button data-act="presenter">${FF.icon('info')} ${presenterOn() ? 'Hide' : 'Show'} presenter notes</button><button data-act="go" data-to="#/settings/demo">${FF.icon('refresh')} Demo scenarios</button><button data-act="hub">${FF.icon('left')} Demo launcher</button><hr style="margin:4px 0"><button data-act="lock">${FF.icon('lock')} Lock · switch person</button>`; });
  FF.act('store', (d) => { $('.pop')?.remove(); if (d.id === FF.db.storeId) return; if (FF.db.org.plan !== 'PREMIUM') return FF.modal({ title: 'More than one store is part of Premium', size: 'narrow', body: `<p>This shop is on Pro, which covers one store. Premium adds switching between stores, stock transfer suggestions and combined reports.</p>`, footer: `<button class="btn" data-act="close">Not now</button><button class="btn btn-p" data-act="go" data-to="#/settings/plan">See plans</button>` }); FF.modal({ title: 'The Surat store isn’t set up yet', size: 'narrow', body: `<p>Premium is active, so you can add it. This demo holds data for the Ahmedabad store only.</p>`, footer: `<button class="btn" data-act="close">Close</button><button class="btn btn-p" data-act="go" data-to="#/onboarding">Open new-shop setup</button>` }); });
  FF.act('presenter', () => { try { localStorage.setItem('ff2_presenter', presenterOn() ? '0' : '1'); } catch (e) {} $('.pop')?.remove(); FF._noteHidden = false; FF.render(); });
  FF.act('lock', () => { FF.setMe(null); $('.pop')?.remove(); L.who = null; L.v = ''; L.tab = 'staff'; FF.render(); });
  FF.act('hub', () => { location.href = 'index.html'; });

  /* ---------- login: who are you → your own PIN (discrete digit cells, as in the real console) ---------- */
  const L = { tab: 'staff', who: null, v: '', fails: 0, until: 0, sent: false, err: '' };
  const login = () => { const st = FF.store(), s = L.who && FF.db.staff.find((x) => x.id === L.who);
    const right = L.tab === 'owner' ? `<div class="eyebrow">Owner sign-in</div><h2 class="mt8">Sign in with your phone</h2><p class="small muted mt4 mb16">We send a one-time code to the owner’s registered number.</p><form class="col" data-submit="${L.sent ? 'l-otp' : 'l-send'}">${U.field('Mobile number', `<input name="phone" type="tel" required pattern="[6-9][0-9 ]{9,11}" value="98250 11001" ${L.sent ? 'readonly' : ''} data-msg="Enter the owner's registered mobile number">`)}${L.sent ? U.field('6-digit code', '<input name="otp" required pattern="[0-9]{6}" inputmode="numeric" maxlength="6" autocomplete="one-time-code" data-msg="Enter the 6-digit code" style="font-family:var(--mono);letter-spacing:.3em;font-size:18px">', 'Demo code: 123456') : ''}<button class="btn btn-p btn-l">${L.sent ? 'Verify and sign in' : 'Send code'}</button></form><button class="link small mt16" data-act="l-tab" data-v="staff">← Staff sign-in</button>`
      : !s ? `<div class="eyebrow">Showroom console</div><h2 class="mt8">Who’s signing in?</h2><p class="small muted mt4 mb16">Tap your name, then your own 4-digit PIN.</p><div class="who">${FF.db.staff.filter((x) => x.active).map((x) => `<button data-act="l-pick" data-id="${x.id}"><span class="avatar lg">${esc(x.code)}</span><span><b class="inkc">${esc(x.name)}</b><br><span class="tiny muted">${FF.TAX.roles[x.role]}</span></span></button>`).join('')}</div><div class="row between mt24"><button class="link small" data-act="l-tab" data-v="owner">Owner? Sign in with phone</button><span class="tiny muted">Demo PIN for everyone: 1111</span></div>`
      : `<button class="link small" data-act="l-pick" data-id="">← Not ${esc(s.name.split(' ')[0])}?</button><div class="row mt16" style="justify-content:center"><span class="avatar lg">${esc(s.code)}</span></div><h2 class="mt12 center">Hello, ${esc(s.name.split(' ')[0])}</h2><p class="small muted center mt4">Enter your 4-digit PIN</p><div class="pindots ${L.err ? 'shake' : ''}" id="lgdots">${[0, 1, 2, 3].map((i) => `<i class="${i < L.v.length ? 'f' : ''}"></i>`).join('')}</div><div class="pinpad">${[1, 2, 3, 4, 5, 6, 7, 8, 9].map((n) => `<button data-act="lg-k" data-k="${n}">${n}</button>`).join('')}<button data-act="lg-k" data-k="clr" style="font-size:11px;border-color:transparent;background:none;letter-spacing:.1em">CLEAR</button><button data-act="lg-k" data-k="0">0</button><button data-act="lg-k" data-k="del" style="border-color:transparent;background:none" aria-label="Delete">⌫</button></div><p class="tiny center mt16 ${L.err ? 'bad' : 'muted'}" role="${L.err ? 'alert' : ''}">${esc(L.err || 'Forgot it? A manager can reset it in Setup → Staff.')}</p>`;
    return `<div class="login"><div class="l-art"><div class="row"><span class="monogram" style="width:40px;height:40px;font-size:22px">F</span><div><div class="brandname" style="font-size:22px">FitFirst</div><div class="brandsub">Showroom console</div></div></div><div><h1>Floor, stock, counter and results — <span class="it">one console.</span></h1><p class="mt16" style="max-width:44ch;font-size:15px">For salespeople serving shoppers, the team adding stock, the counter, and the owner watching aged stock clear.</p></div><div class="row between tiny mono muted" style="border-top:1px solid var(--line);padding-top:16px"><span>${esc(st.name)} · ${esc(st.city)}</span><span>Pilot · week ${Math.min(FF.db.settings.pilot.weeks, Math.floor((Date.now() - FF.db.settings.pilot.start) / FF.DAY / 7) + 1)} of ${FF.db.settings.pilot.weeks}</span></div></div>
      <div class="l-form"><div style="width:min(420px,100%)" tabindex="-1" id="lgbox">${right}<p class="tiny muted mt32 center"><a href="index.html">← Demo launcher</a></p></div></div></div>`; };
  FF.act('l-tab', (d) => { L.tab = d.v; L.sent = false; FF.render(); });
  FF.act('l-pick', (d) => { if (d.id && Date.now() < L.until) return FF.toast('Too many tries — wait ' + Math.ceil((L.until - Date.now()) / 1000) + ' s', 'bad'); L.who = d.id || null; L.v = ''; L.err = ''; FF.render(); });
  FF.act('lg-k', (d) => { if (d.k === 'del') L.v = L.v.slice(0, -1); else if (d.k === 'clr') L.v = ''; else if (L.v.length < 4) L.v += d.k; L.err = ''; FF.render();
    if (L.v.length === 4) { const s = FF.db.staff.find((x) => x.id === L.who); setTimeout(() => { if (L.v === s.pin) return enter(s); L.fails++; L.v = ''; if (L.fails >= 5) { L.fails = 0; L.until = Date.now() + 30000; L.who = null; FF.render(); return FF.toast('Locked for 30 seconds after 5 wrong tries', 'bad'); } L.err = `That PIN didn’t match — ${5 - L.fails} tries left`; FF.render(); }, 160); } });
  document.addEventListener('keydown', (e) => { if (FF.me() || !L.who || $('.scrim')) return; if (/^[0-9]$/.test(e.key)) FF.acts['lg-k']({ k: e.key }); else if (e.key === 'Backspace') FF.acts['lg-k']({ k: 'del' }); });
  FF.act('l-send', (f) => { if (!FF.db.staff.some((s) => s.role === 'OWNER' && s.phone.replace(/\s/g, '') === f.phone.replace(/\s/g, ''))) return FF.toast('No owner account uses that number', 'bad'); L.sent = true; FF.render(); FF.toast('Code sent by SMS (simulated)', 'ok'); });
  FF.act('l-otp', (f) => { if (f.otp !== '123456') return FF.toast('That code is not right', 'bad'); enter(FF.db.staff.find((s) => s.role === 'OWNER')); });
  const enter = (s) => { L.fails = 0; L.sent = false; L.who = null; L.v = ''; L.err = ''; FF.setMe(s.id); FF.audit('Signed in', 'Session', FF.TAX.roles[s.role]); FF.save(); const r = route(); if (!FF.db.settings.onboarded && s.role === 'OWNER') location.hash = '#/onboarding'; else if (!FF.pages[r.name] || !can(FF.pages[r.name])) location.hash = '#/home'; FF.render(); FF.toast('Welcome, ' + s.name.split(' ')[0], 'ok'); };

  /* ---------- Today: one screen per role ---------- */
  FF.page('home', { title: 'Today', icon: 'home', roles: ALL, render: () => {
    const me = FF.me(), db = FF.db, t0 = new Date().setHours(0, 0, 0, 0), c = FF.counts(), hr = new Date().getHours();
    const greet = `${hr < 12 ? 'Good morning' : hr < 17 ? 'Good afternoon' : 'Good evening'}, ${esc(me.name.split(' ')[0])}`, date = new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' });
    const waiting = db.visits.filter((v) => v.status === 'WAITING').sort((a, b) => (a.waitingSince || a.at) - (b.waitingSince || b.at)), mine = db.visits.filter((v) => v.staff === me.id && ['ASSIGNED', 'TRYING'].includes(v.status)), salesT = db.sales.filter((s) => s.at >= t0);
    const help = db.help.filter((h) => !h.done);
    const helpRows = help.map((h) => `<div class="note n-bad row mb8"><span class="grow"><b>Help requested</b> · ${esc(h.where)}${h.text ? ' · ' + esc(h.text) : ''} · ${FF.ago(h.at)} ago</span><button class="btn btn-s" data-act="help-done" data-id="${h.id}">I’m on it</button></div>`).join('');
    const vcard = (v) => { const p = v.profiles[0] || {}, w = Date.now() - (v.waitingSince || v.at); return `<div class="qcard ${v.status === 'WAITING' && w > 5 * 60000 ? 'urgent' : ''}"><div class="row between"><a class="code" style="font-size:18px;text-decoration:none" href="#/session/${v.code}">${v.code}</a><span class="small ${w > 5 * 60000 && v.status === 'WAITING' ? 'bad b' : 'muted'}">${v.status === 'WAITING' ? 'waiting ' + FF.ago(v.waitingSince || v.at) : U.status(v.status)}</span></div><div class="small">${esc([FF.TAX.depts[p.dept], (p.cats || []).map(FF.catName).join(', '), p.occasion].filter(Boolean).join(' · '))}</div><div class="row wrap gap6">${U.badge(v.shortlist.length + ' to try', v.shortlist.length ? 'brass' : '')}${v.lang !== 'en' ? U.badge(v.lang === 'gu' ? 'ગુજરાતી' : 'हिन्दी', 'info') : ''}</div>${v.status === 'WAITING' ? `<button class="btn btn-p btn-s" data-act="v-claim" data-code="${v.code}">Claim — I’ll help</button>` : `<a class="btn btn-s" href="#/session/${v.code}">Continue</a>`}</div>`; };

    if (me.role === 'STAFF') { const myS = db.sales.filter((s) => s.staff === me.id && s.at >= Date.now() - 30 * FF.DAY), spiff = FF.sum(myS.flatMap((s) => s.lines), (l) => (l.aged && l.rec ? 100 : 0));
      return `<div class="ph1"><div><div class="eyebrow">${date}</div><h1 class="mt8">${greet}</h1><p>${waiting.length ? `${waiting.length} shopper${waiting.length > 1 ? 's are' : ' is'} waiting for help.` : 'Nobody is waiting right now.'}</p></div><div class="row wrap"><a class="btn btn-p btn-l" href="kiosk.html?mode=assisted">${FF.icon('spark')} Start a consultation</a><a class="btn btn-l" href="#/billing">${FF.icon('bill')} New bill</a></div></div>${helpRows}
        <div class="grid g2 stack"><div><div class="row between mb8"><h2>Waiting now</h2><button class="btn btn-s btn-g" data-act="sim-walkin">${FF.icon('plus')} Simulate a walk-in</button></div>${waiting.map(vcard).join('') || `<div class="card">${U.empty('users', 'No one waiting', 'New shoppers appear here the moment they finish on the kiosk or their phone.')}</div>`}</div>
        <div><h2 class="mb8">With me</h2>${mine.map(vcard).join('') || `<div class="card">${U.empty('hanger', 'No fittings in progress', 'Claim a waiting shopper to start.')}</div>`}<div class="grid g2 mt16">${U.kpi('My sales · 30 days', FF.inrK(FF.sum(myS, (s) => s.total)), `${myS.length} bills in my name`)}${U.kpi('Incentive earned', FF.inr(spiff), 'for aged pieces sold')}</div></div></div>`; }

    if (me.role === 'INTAKE') return `<div class="ph1"><div><div class="eyebrow">${date}</div><h1 class="mt8">${greet}</h1><p>Your stock tasks for today.</p></div><a class="btn btn-p btn-l" href="#/intake">${FF.icon('camera')} Add stock</a></div>
      <div class="grid g4">${[['review', 'eye', 'AI review', c.review, 'pieces waiting for a quick check'], ['labels', 'print', 'Labels', c.labels, 'barcode labels to print'], ['import', 'refresh', 'Sync issues', c.import, 'rows to resolve from billing software'], ['count', 'calc', 'Stock count', FF.db.counts.length, 'racks counted so far']].map(([h, ic, l, n, s]) => `<a class="kpi card lift reveal" style="text-decoration:none" href="#/${h}"><div class="k-l">${FF.icon(ic)} ${l}</div><div class="k-v">${n}</div><div class="k-s">${s}</div></a>`).join('')}</div>
      <div class="sec"><div class="sh"><h2>Oldest stock without full photos</h2><span class="small muted">photograph these first — that is where the money is stuck</span></div>${U.table('old', [{ k: 'n', l: 'Piece', html: (p) => `<div class="row"><div class="thumb">${FF.garment(p)}</div><b class="inkc">${esc(p.name)}</b></div>` }, { k: 'a', l: 'In stock', html: (p) => U.ageBadge(p) }, { k: 'r', l: 'Rack', html: (p) => `<span class="mono">${p.rack}</span>` }, { k: 'x', l: '', html: (p) => `<a class="btn btn-s" href="#/intake/${p.id}">Full intake</a>` }], db.products.filter((p) => p.status === 'LIVE' && p.intake === 'QUICK').sort((a, b) => a.receivedAt - b.receivedAt).slice(0, 5), { per: 5 })}</div>`;

    /* owner and manager */
    const wk = FF.metrics(7), m1 = FF.metrics(1), agedWeek = wk.agedCleared, agedPcs = wk.S.flatMap((s) => s.lines.filter((l) => l.aged)).length;
    const todo = [];
    if (waiting.length) todo.push(['warn', 'users', `${waiting.length} shopper${waiting.length > 1 ? 's' : ''} waiting`, 'Longest wait ' + FF.ago(Math.min(...waiting.map((v) => v.waitingSince || v.at))), '#/sessions', 'Open']);
    if (c.review) todo.push(['warn', 'eye', `${c.review} new piece${c.review > 1 ? 's' : ''} to check before going live`, 'AI was unsure about a few fields', '#/review', 'Review']);
    if (c.import) todo.push(['warn', 'refresh', `${c.import} billing-software sync issue${c.import > 1 ? 's' : ''}`, 'Stock may disagree with Tally', '#/import', 'Resolve']);
    db.devices.filter((d) => d.active && d.calib && d.calib < Date.now()).forEach((d) => todo.push(['warn', 'camera', `${esc(d.name)} needs recalibrating`, 'Camera tone checks are paused on it', '#/settings/devices', 'Calibrate']));
    if (!db.dayCloses.some((d) => d.date === FF.day(Date.now() - FF.DAY))) todo.push(['', 'cash', 'Yesterday’s counter was not closed', 'Cash count and Z-report pending', '#/dayclose', 'Close day']);
    if (c.gaps) todo.push(['info', 'target', `${c.gaps} new demand gap${c.gaps > 1 ? 's' : ''}`, 'Shoppers asked for something you don’t stock', '#/gaps', 'See list']);
    const days = []; for (let d = 13; d >= 0; d--) { const a = new Date(Date.now() - d * FF.DAY).setHours(0, 0, 0, 0), b = a + FF.DAY; days.push({ l: FF.fmtDate(a), v: db.visits.filter((v) => v.at >= a && v.at < b && v.status !== 'BROWSING').length }); }
    return `<div class="ph1"><div><div class="eyebrow">${date} · ${esc(FF.store().name)}</div><h1 class="mt8">${greet}</h1><p>Here is your showroom at a glance.</p></div><div class="row wrap"><button class="btn" data-act="i-wa">${FF.icon('wa')} Today’s summary</button><a class="btn btn-p" href="#/analytics">${FF.icon('chart')} Pilot analytics</a></div></div>${helpRows}
      <div class="valueline reveal"><div class="big">${FF.inrK(agedWeek)}</div><div><b style="color:inherit">of older stock sold in the last 7 days</b><p>${agedPcs} pieces that had passed their fresh window. ${wk.lift == null ? `The control group needs a few more visits before the extra effect can be measured.` : `Shoppers who saw FitFirst’s picks bought older pieces ${Math.round(wk.lift * 100)}% more often than the control group.`}</p></div><a class="btn btn-g" style="color:inherit;margin-left:auto" href="#/clearance">Clearance ${FF.icon('right')}</a></div>
      <div class="grid g4 mt16">${U.kpi('Consultations today', db.visits.filter((v) => v.at >= t0 && v.status !== 'BROWSING').length, `${waiting.length} waiting now`)}${U.kpi('Sales today', FF.inrK(FF.sum(salesT, (s) => s.total)), `${salesT.length} bills · ${salesT.filter((s) => s.visit).length} through FitFirst`)}${U.kpi('Bought a pick · 7 days', FF.pct(wk.recBuy, wk.sessions), `${wk.recBuy} of ${wk.sessions} consultations`, { info: 'Consultations where at least one recommended piece was bought, divided by all consultations. One shopper buying three pieces counts once.' })}${U.kpi('Try-ons this month', `${db.settings.tryon.used}<span class="small muted"> / ${db.settings.tryon.monthly}</span>`, 'plan allowance')}</div>
      <div class="split sec"><div><div class="sh"><h2>Needs your attention</h2><span class="small muted">${todo.length} item${todo.length === 1 ? '' : 's'}</span></div><div class="card pad0">${todo.map((x) => `<a class="row" style="padding:14px 18px;border-bottom:1px solid var(--line);text-decoration:none" href="${x[4]}"><span class="${x[0]}">${FF.icon(x[1])}</span><div class="grow"><div class="b">${x[2]}</div><div class="small muted">${x[3]}</div></div><span class="btn btn-s">${x[5]}</span></a>`).join('') || U.empty('check', 'All clear', 'Nothing needs you right now.')}</div>
        <div class="card mt16"><div class="row between"><h3>Consultations · last 14 days</h3>${U.demo()}</div><div class="mt12">${FF.chart.bars(days, { h: 150, label: 'Consultations per day' })}</div></div></div>
      <div><div class="sh"><h2>On the floor</h2><a class="link small" href="#/sessions">All sessions</a></div>${db.visits.filter((v) => ['WAITING', 'ASSIGNED', 'TRYING'].includes(v.status)).slice(-5).reverse().map(vcard).join('') || `<div class="card">${U.empty('users', 'Quiet right now', 'Shoppers appear here as soon as they finish a consultation.', `<button class="btn btn-s" data-act="sim-walkin">Simulate a walk-in</button>`)}</div>`}</div></div>`; } });

  /* daily ledger for the Baseline Log, derived once from the demo bills */
  const ensureLedger = () => { const db = FF.db; if (db.ledger) return; db.ledger = db.baseline.map((b) => { const S = db.sales.filter((s) => FF.day(s.at) === b.date); return { date: b.date, tx: S.length, rev: FF.sum(S, (s) => s.total), units: S.length ? +(FF.sum(S, (s) => FF.sum(s.lines, (l) => l.qty)) / S.length).toFixed(2) : 0, notes: b.note || '', kiosk: b.kiosk, footfall: b.footfall, by: 'Imported from bills' }; }); FF.save(); };
  FF.boot = () => { FF.load(); FF.theme(); ensureLedger(); FF.onSync = (old) => { const was = old.visits.filter((v) => v.status === 'WAITING').length, now = FF.db.visits.filter((v) => v.status === 'WAITING').length; if (!$('.scrim') && FF.me()) FF.render(); if (now > was && FF.me()) FF.toast('New shopper waiting', 'ok'); }; FF.render(); };
})();
